import sys, json, os; sys.path.insert(0, '.')
from docx_helpers import *
import packdata as PD, figs
import numpy as np, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
MK = json.load(open('market.json')); MF = {f['id']: f for f in MK['facts']}
BAL = 'The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources.'
CONF = 'ALL INFORMATION IN THIS DOCUMENT, IN THE OTHER DOCUMENTS OF THIS PACK AND IN THE DATA ROOM IS CONFIDENTIAL. It is provided only under the non-disclosure agreement between the recipient and Jalour, and must not be disclosed, copied, forwarded or used for any other purpose.'
def build_memo_combined(path, workdir, Te=62.5):
    C = PD.build_combined(Te); T = C['T']; G, L = C['GS'], C['LA']; PJ = [('Green Square', G), ('L\'avenir', L)]
    os.makedirs(workdir, exist_ok=True)
    fg = figs.make(G, os.path.join(workdir, 'figs_gs')); fl = figs.make(L, os.path.join(workdir, 'figs_la')); FIG = {'GS': fg, 'LA': fl}
    A = C['A']; B = C['B']; S1 = B['S1']; S2 = B['S2']; S3 = B['S3']; sp = C['sponsor']; ai = A['inv']
    mult = G['B']['mult']; inst = mult*Te/12; pmG = G['B']['pay_months']; pmL = L['B']['pay_months']
    # combined cumulative chart
    f, ax = plt.subplots(figsize=(7.2, 3.4)); M2 = np.array(sp['months']); n = 28
    ax.plot(M2[:n], np.array(sp['self_cum'])[:n], color='#1B2F4B', lw=2, label='Green Square'); ax.plot(M2[:n], np.array(sp['other_cum'])[:n], color='#B88A3E', lw=2, label='L\'avenir'); ax.plot(M2[:n], np.array(sp['comb_cum'])[:n], color='#B23A3A', lw=2.4, label='Combined')
    ax.axhline(0, color='#9AA3AF', lw=0.8); ax.set_xlabel('Month on the common calendar (Green Square launch = month 1; L\'avenir launches in month 7)'); ax.set_ylabel('Cumulative net cash flow, EGP million'); ax.legend(frameon=False, fontsize=8); ax.spines[['top', 'right']].set_visible(False); f.tight_layout(); figc = os.path.join(workdir, 'fig_comb.png'); f.savefig(figc, dpi=170); plt.close(f)
    # investor cumulative chart (combined)
    f, ax = plt.subplots(figsize=(7.2, 3.2)); mo = np.arange(3, 181, 3)[:len(ai['Base']['flows'])] - 6
    ax.plot(mo, np.cumsum(ai['Base']['flows']), color='#1B2F4B', lw=2, label='Option A (base)'); ax.plot(mo, np.cumsum(S1['Base']['flows']), color='#B88A3E', lw=2, label='Option B')
    ax.axhline(0, color='#9AA3AF', lw=0.8); ax.set_xlim(-6, 74); ax.set_xlabel('Month on the common calendar (Green Square launch = month 1)'); ax.set_ylabel('Cumulative investor cash flow, EGP million'); ax.legend(frameon=False, fontsize=8); ax.spines[['top', 'right']].set_visible(False); f.tight_layout(); figi = os.path.join(workdir, 'fig_inv.png'); f.savefig(figi, dpi=170); plt.close(f)
    def one(toc=None):
        NAME = 'Green Square and L\'avenir'
        d = Doc(f'{NAME} - Investment Memorandum (EGP 125 million combined)', f'Jalour Developments  |  {NAME} Investment Memorandum  |  Strictly private and confidential'); dd = d.d
        for _ in range(5): dd.add_paragraph()
        d.p('STRICTLY PRIVATE AND CONFIDENTIAL', bold=True, size=10, color=BRASS)
        d.p(NAME, bold=True, size=32, color=NAVY, after=2)
        d.p('Two commercial and office developments, El Mostakbal City, Cairo', size=15, color=INK, after=14)
        d.p('INVESTMENT MEMORANDUM', bold=True, size=14, color=NAVY, after=2)
        d.p('Private placement of EGP 125 million (USD 2.6 million at EGP 48 per USD): EGP 62.5 million in each project', size=12, after=2)
        d.p('Option A: units. Option B: cash. One option applies to both projects.', size=12, after=36)
        d.p('ALL INFORMATION IN THIS DOCUMENT IS CONFIDENTIAL AND SUBJECT TO THE NON-DISCLOSURE AGREEMENT.', bold=True, size=9.5, color=BRASS, after=8)
        d.p('Issued by Jalour Developments, a subsidiary of Al Jalal Holding, Cairo', size=10.5, after=2)
        d.p('October 2026. Draft for discussion with the named investor only.', size=10.5, color=GREY)
        d.h1('Important notice')
        d.callout('**' + CONF + '**')
        for t in ['This memorandum has been prepared by Jalour Developments (Jalour) for the sole use of the investor to whom it is addressed. It is confidential. It must not be copied, distributed or disclosed to any other person without Jalour\'s written consent. The non-disclosure agreement covers every document, figure and statement in this pack, including the financial information of both projects.',
                  'It is not an offer to the public and is not a prospectus. It has not been reviewed or approved by any regulator. Whether this placement requires any regulatory filing, approval or exemption in Egypt or elsewhere is a matter for legal counsel; nothing here is legal, tax or investment advice.',
                  'All forecasts, returns, multiples, internal rates of return, cash flows and market statements are projections or reported third-party statements, not statements of fact or guarantees. Actual results may differ materially. Every return figure is labelled with its case (base, downside or upside).',
                  'Figures come from the Jalour financial model for the two projects and are reproduced in the Financial Annex, whose Combined_Summary sheet is the reference for every number below. Market data are taken from third-party publications identified in the text and in Appendix D; Jalour has not independently verified them. Property listings are asking prices, not transaction prices.',
                  'Items shown in square brackets are provided after the investor signs the non-disclosure agreement. Terms are indicative until set out in definitive agreements, which prevail over this memorandum.',
                  'Jalour may raise further capital at project or holding level, subject to the investor\'s stated rights as to ranking, collateral and information. This memorandum creates no exclusivity in favour of any investor.',
                  'Each project is held in its own company, with no cross-collateral and no cross-default between the projects. The two projects are presented together because this placement is a single investment of EGP 62.5 million in each.']: d.p(t)
        d.h1('Contents')
        items = ['1. Executive summary', '2. Transaction overview', '3. Investment thesis', '4. Market analysis', '5. Project descriptions', '6. The Al Ahly Sabbour agreements and consents', '7. Sponsor and management', '8. Business plan and assumptions', '9. Sales and collections model', '10. Cost model', '11. Funding plan, use of funds and combined cash position', '12. Investment terms', '13. Returns analysis and sensitivities', '14. Security and ranking', '15. Governance and information rights', '16. Exit and liquidity', '17. Risk factors', '18. Tax and legal considerations', 'Appendices']
        for t in items:
            par = dd.add_paragraph(); par.paragraph_format.space_after = Pt(3); par.paragraph_format.tab_stops.add_tab_stop(Cm(16.3), alignment=2, leader=1)
            r = par.add_run(t + '\t' + (str(toc.get(t, '')) if toc else '')); r.font.size = Pt(11)
        # 1
        d.h1('1. Executive summary')
        d.p(f'Jalour is raising EGP 125 million from a single investor: EGP {fmt(Te,1)} million into Green Square and EGP {fmt(Te,1)} million into L\'avenir. The projects are two commercial and office developments in El Mostakbal City, east of New Cairo, of {fmt(G["info"]["bua"],0)} m2 and {fmt(L["info"]["bua"],0)} m2 of built-up area on plots of {fmt(G["info"]["land"],0)} and {fmt(L["info"]["land"],0)} m2. Both plots belong to Al Ahly Sabbour. Jalour is developer and operator of each: it designs, obtains permits, builds to core-and-shell standard, markets, sells, collects and operates. Collections are shared 35% to the landowner (subject to minimum guarantees of EGP {fmt(G["info"]["guarantee"],0)} million and EGP {fmt(L["info"]["guarantee"],0)} million over six years) and 65% to Jalour.')
        d.p('The investor chooses one of two instruments at signing, and the choice applies to both projects:')
        d.bullets([f'**Option A, units.** In each project, units with a face value of EGP {fmt(G["A"]["face"],0)} million, twice the ticket, priced at the launch list, allocated from the first two sales tranches: EGP {fmt(A["face"],0)} million in total. At the delivery list prices the units are worth EGP {fmt(A["value"],0)} million. Projected investor IRR on the combined EGP 125 million: {pct(ai["Base"]["irr"])} base, {pct(ai["Downside"]["irr"])} downside, {pct(ai["Upside"]["irr"])} upside.',
                   f'**Option B, cash.** EGP {fmt(mult*Te,2)} million ({mx(mult,1)} the ticket) from each project, EGP {fmt(mult*T,1)} million in total, in 12 equal quarterly instalments per project of EGP {fmt(inst,2)} million after a 24-month grace period (Green Square months {pmG[0]} to {pmG[-1]}; L\'avenir months {pmL[0]} to {pmL[-1]}). Projected investor IRR {pct(S1["Base"]["Base"]["irr"] if False else S1["Base"]["irr"])}, contractual if Jalour pays.'])
        d.table([['Key figures (EGP million unless stated)', 'Green Square', 'L\'avenir', 'Combined'],
                 ['Investor ticket', fmt(Te, 1), fmt(Te, 1), fmt(T, 1)], ['Modelled peak cumulative shortage, base case', fmt(G['fund']['model_peak'], 1), fmt(L['fund']['model_peak'], 1), fmt(-sp['comb_min'], 1)],
                 ['Total uses at the funding peak', fmt(G['fund']['total'], 1), fmt(L['fund']['total'], 1), fmt(G['fund']['total']+L['fund']['total'], 1)], ['Total sales in the sales plans', fmt(G['info']['total80'], 0), fmt(L['info']['total80'], 0), fmt(G['info']['total80']+L['info']['total80'], 0)],
                 ['Jalour net cash flow, nominal', fmt(G['base']['net'], 1), fmt(L['base']['net'], 1), fmt(G['base']['net']+L['base']['net'], 1)], ['NPV of Jalour net cash flow at 14%', fmt(G['base']['npv'], 1), fmt(L['base']['npv'], 1), fmt(G['base']['npv']+L['base']['npv'], 1)],
                 ['Handover (project month)', str(G['info']['delivery']), str(L['info']['delivery']), ''], ['Option A units, face value', fmt(G['A']['face'], 0), fmt(L['A']['face'], 0), fmt(A['face'], 0)], ['Option B total return', fmt(mult*Te, 1), fmt(mult*Te, 1), fmt(mult*T, 1)]], [6.8, 3.1, 3.1, 3.3], 'Headline figures', 1, font=9.5)
        d.p('Three points deserve the investor\'s attention before the detail.', bold=True, keep=True)
        gcs = [(G['prices']['final'][0]/G['prices']['launch'][0]-1), (G['prices']['final'][1]/G['prices']['launch'][1]-1), (L['prices']['final'][0]/L['prices']['launch'][0]-1), (L['prices']['final'][1]/L['prices']['launch'][1]-1)]
        d.bullets([f'**Pricing.** The plans rely on list prices rising from launch to delivery by {gcs[0]*100:.0f}% (retail) and {gcs[1]*100:.0f}% (offices) in Green Square and by {gcs[2]*100:.0f}% and {gcs[3]*100:.0f}% in L\'avenir. Recent evidence of price growth is lower at its low end and similar at its high end (section 4). Option B removes unit price exposure; Option A does not.',
                   f'**Timing of cash.** The model collects each project\'s delivery payment (20% to 25% of price) on a contractual milestone ahead of handover. If it were collected at handover the peak funding need would be EGP {fmt(G["fund"]["stress_peak"],0)} million (Green Square) and EGP {fmt(L["fund"]["stress_peak"],0)} million (L\'avenir) instead of EGP {fmt(G["fund"]["model_peak"],1)} and {fmt(L["fund"]["model_peak"],1)} million. Jalour has said it will cover project funding gaps above project cash from its cash reserves and from cash generated by other projects it is constructing (section 11).',
                   f'**Both projects together.** The combined base-case position is lowest at EGP {fmt(-sp["comb_min"],1)} million in month {sp["comb_min_m"]} and positive from month {sp["comb_pos_month"]} (common calendar: month 1 is the Green Square launch; L\'avenir launches in month 7), but in the stress cases both projects are short at the same time: the combined peak is EGP {fmt(-sp["scen"]["Delivery payments at handover"]["comb_peak"],0)} million if delivery payments arrive at handover and EGP {fmt(-sp["scen"]["Downside: sales +12 months, prices -10%"]["comb_peak"],0)} million in the downside. One project\'s cash cannot be assumed to fund the other.'])
        d.p(BAL + ' This applies in each project.', italic=True)
        # 2
        d.h1('2. Transaction overview')
        d.h2('2.1 Parties and instrument')
        d.table([['Item', 'Description'], ['Sponsor and developer', 'Jalour Developments, the real estate arm of Al Jalal Holding, Cairo'], ['Landowner', 'Al Ahly Sabbour (both plots)'], ['Issuers', 'One project company for each development [names and jurisdiction to be confirmed]'],
                 ['Investor', '[Name of investor]'], ['Instrument', 'Contractual entitlement to units (Option A) or to cash payments (Option B), in each project. Whether it is documented as equity, a loan or a contractual entitlement is to be confirmed by counsel and affects tax, regulation and enforceability'], ['Ticket', 'EGP 125 million in total: EGP 62.5 million into Green Square and EGP 62.5 million into L\'avenir'],
                 ['Choice', 'Option A or Option B, selected at signing; the same option applies to both projects'], ['Balance of funding', BAL + ' This applies in each project.']], [4.2, 12.1], 'Principal terms', -1, bold_first_col=True)
        d.h2('2.2 Conditions and timetable')
        d.bullets(['Signature of the non-disclosure agreement (template provided with this pack), which covers all information provided.', 'Due diligence by the investor and its advisers on the data room (Due Diligence Memorandum).', 'Written consent of Al Ahly Sabbour to the unit allocation (Option A) and to any assignment or encumbrance that affects its share, for each project.', 'Definitive agreements for each project, including security documents reviewed by counsel for both sides.', f'Funding in cash into each project company, expected in project month {3} for Green Square and month {12} for L\'avenir (the months the landlord down payments fall due in the model).'])
        d.h2('2.3 No exclusivity; further capital')
        d.p('Jalour may raise further capital at project or holding level, subject to the investor\'s stated rights: ranking of the investor\'s claim, collateral over the earmarked units, and information rights. A project company will not grant security over the investor\'s earmarked units or rank any new instrument ahead of the investor\'s entitlement without the consent given in the definitive agreements.')
        d.h2('2.4 Separate projects, single investment')
        d.p('Each project is held in its own company. There is no cross-collateral and no cross-default between the projects. The investor\'s EGP 62.5 million in each project is that project\'s funding, not a restricted or segregated account; payment protections are contractual and described in section 14. The investment is made as one transaction under one non-disclosure agreement.')
        d.h2('2.5 Confidentiality')
        d.p('Everything in this pack is confidential: this memorandum, the presentation, the Financial Annex, the Due Diligence Memorandum, the data room and any information about either project, the landowner, Jalour or Al Jalal Holding that the investor receives. The non-disclosure agreement template in this pack is to be signed before the sponsor, permit, title and landlord-consent materials are released.', bold=False)
        # 3
        d.h1('3. Investment thesis', page_break=False)
        d.p('The case for the investment, with the main reservation against each point:', keep=True)
        d.table([['Thesis', 'Reservation'],
                 [f'Two defined assets of G+2 buildings ({fmt(G["info"]["bua"],0)} and {fmt(L["info"]["bua"],0)} m2) in a state-planned city of about 11,000 feddans and about 1 million planned residents.', 'Mostakbal City is early in its build-out; current resident population and occupancy were not found in public sources.'],
                 ['Land is owned by an established developer, Al Ahly Sabbour, and is not an acquisition cost for Jalour: the landowner is paid from collections.', f'The landlord guarantees (EGP {fmt(G["info"]["guarantee"],0)} million and EGP {fmt(L["info"]["guarantee"],0)} million over six years) are payable even if sales are slow.'],
                 ['Sales begin at launch lists of EGP 135,000 to 225,000 (Green Square) and 160,000 to 250,000 (L\'avenir) per m2, with list price steps built into the plans.', 'Asking prices for Mostakbal City offices today are about EGP 106,000 to 120,000 per m2; the plans assume higher.'],
                 [f'Project funding peaks at EGP {fmt(G["fund"]["model_peak"],1)} million and EGP {fmt(L["fund"]["model_peak"],1)} million in the base case, in different months; the projects generate EGP {fmt(G["base"]["net"]+L["base"]["net"],0)} million of net cash flow.', f'Combined funding peak is EGP {fmt(-sp["scen"]["Delivery payments at handover"]["comb_peak"],0)} million if delivery payments arrive at handover.'],
                 ['Two ways to participate: units with price upside, or cash with a fixed return, across two projects with different timelines.', 'Option A carries price and resale risk; Option B depends on Jalour\'s ability to fund payouts during the construction peak.']], [8.3, 8.0], 'Thesis and reservations', -1, font=9.5)
        # 4
        d.h1('4. Market analysis')
        d.p('Market statements below are reported by the third parties named. They are drawn from published summaries as at October 2026; Jalour has not audited them. Where sources use different definitions (for example, Knight Frank and JLL measure Cairo office stock differently) the figures are not additive.')
        d.h2('4.1 Cairo and New Cairo offices')
        d.bullets([MF['kf_stock']['text'] + f' ({MF["kf_stock"]["src"]}).', MF['kf_nc']['text'] + f' ({MF["kf_nc"]["src"]}).', MF['jll_vac']['text'] + f' ({MF["jll_vac"]["src"]}).', MF['kf_rent']['text'] + f' ({MF["kf_rent"]["src"]}).'])
        d.p('Reading across: occupancy and rents are firm today, but the pipeline is large relative to stock. New Cairo is where most of that supply will land, so absorption of new supply by 2029 is the main market risk for the offices.')
        d.h2('4.2 Retail and commercial')
        d.bullets([MF['jll_retail']['text'] + f' ({MF["jll_retail"]["src"]}).', MF['hap']['text'] + f' ({MF["hap"]["src"]}).', 'Retail rents rose 0.8% to 3.6% y/y in Q1 2026 depending on format (JLL via Invest-Gate); vacancy fell from 9.2% in Q2 2024 to 7.2% in Q2 2025 (JLL).'])
        d.p('The product, ground-floor retail beneath two office floors in a G+2 form, is close to the mixed-use commercial boulevards now being launched in Mostakbal City. Retail sales in a new city depend on resident and worker footfall that builds over years.')
        d.h2('4.3 Mostakbal City')
        d.bullets([MF['mc_scale']['text'] + f' ({MF["mc_scale"]["src"]}).', MF['mc_infra']['text'] + f' ({MF["mc_infra"]["src"]}).', 'Al Ahly Sabbour is active in the city (residential schemes and a mixed-use plot), which supports the landowner\'s interest in the success of these developments (Invest-Gate).'])
        d.h2('4.4 Pricing evidence and the plans')
        rows = [['Measure (EGP per m2)', 'Evidence (asking prices)', 'GS launch', 'GS delivery list', 'LA launch', 'LA delivery list']]
        rows.append(['Offices', '106,000 to 120,000 (Mostakbal City listings)'] + [fmt(x*1000, 0) for x in (G['prices']['launch'][1], G['prices']['final'][1], L['prices']['launch'][1], L['prices']['final'][1])])
        rows.append(['Retail', '139,000 to 325,000 (New Cairo listings, individual)'] + [fmt(x*1000, 0) for x in (G['prices']['launch'][0], G['prices']['final'][0], L['prices']['launch'][0], L['prices']['final'][0])])
        d.table(rows, [2.4, 4.8, 2.3, 2.3, 2.2, 2.3], 'Plan prices against market asking prices (GS = Green Square, LA = L\'avenir)', 2, font=9)
        rows = [['Project and type', 'Launch list', 'Average realised', 'Delivery list', 'Delivery vs launch', 'Delivery list vs today\'s asking']]
        for nm, D in PJ:
            pc = D['pricecmp']; pr = D['prices']
            rows.append([f'{nm}: offices', fmt(pr['launch'][1]*1000, 0), fmt(pr['avg'][1]*1000, 0), fmt(pr['final'][1]*1000, 0), f'+{pc["office_g"]*100:.0f}%', f'+{pc["off_vs_ask"]*100:.0f}% (mid-point 113,000)'])
            rows.append([f'{nm}: retail', fmt(pr['launch'][0]*1000, 0), fmt(pr['avg'][0]*1000, 0), fmt(pr['final'][0]*1000, 0), f'+{pc["retail_g"]*100:.0f}%', 'Within the listed range'])
        d.table(rows, [3.8, 2.2, 2.4, 2.2, 2.4, 3.3], 'Launch, average realised and delivery list prices (EGP per m2)', 1, font=8.5)
        d.p(f'The delivery list is the last list price in each plan and is unchanged to handover. Measured from launch, the blended rise is {G["pricecmp"]["blended"]*100:.0f}% in Green Square and {L["pricecmp"]["blended"]*100:.0f}% in L\'avenir (weighted by the launch tranches), against the 40% to 60% range Jalour expects. Measured from today\'s office asking prices, the delivery lists are +{G["pricecmp"]["off_vs_ask"]*100:.0f}% and +{L["pricecmp"]["off_vs_ask"]*100:.0f}%, or about {G["pricecmp"]["off_cagr"]*100:.0f}% and {L["pricecmp"]["off_cagr"]*100:.0f}% a year measured from today (assumed to be December 2026).')
        d.p('The plans\' launch prices for offices are above current Mostakbal City asking prices, and then rise. New Cairo secondary-market prices rose 3.1% y/y in Q1 2026 (JLL via Enterprise); broker estimates for 2026 price growth are 10% to 16% a year (a blog estimate, not an index). A 40% to 60% rise over three to four years needs about 12% to 13% a year, which is at the upper end of that range and depends on continued inflation (14.5% in August 2026). Sales prices may therefore be lower or slower than planned; section 13 shows the effect.')
        d.h2('4.5 Demand drivers and macro')
        d.bullets([MF['cbe']['text'] + f' ({MF["cbe"]["src"]}).', MF['dev_h1']['text'] + f' ({MF["dev_h1"]["src"]}).', MF['payplan']['text'] + f' ({MF["payplan"]["src"]}).', 'Real estate is widely used in Egypt as an inflation hedge, but affordability is stretched and the share of investor buyers fell in 2025 (Enterprise).'])
        d.h2('4.6 Regulation of off-plan sales')
        d.p(MF['decree']['text'] + f' ({MF["decree"]["src"]}). Jalour\'s position is that this requirement does not apply to these plots; the basis is provided in the data room after the investor signs the non-disclosure agreement. Counsel should confirm which other rules apply to a private placement of this kind. Resale of contracts is common but developer approval and fees are contractual; no specific rule on developer consent to resale was found.')
        # 5
        d.h1('5. Project descriptions')
        for nm, D in PJ:
            I = D['info']; k = D['k']
            d.h2(f'5.{1 if k=="GS" else 2} {nm}')
            d.table([['Item', 'Detail'], ['Land area', f'{fmt(I["land"],0)} m2'], ['Footprint (30% of land)', f'{fmt(I["footprint"],0)} m2'], ['Height', I['height']], ['Retail built-up area', f'{fmt(I["retail"],0)} m2'], ['Office built-up area', f'{fmt(I["office"],0)} m2'], ['Total built-up area', f'{fmt(I["bua"],0)} m2'],
                     ['Finishing standard', 'Core and shell'], ['Sales start', f'Project month {I["sales_start"]}'], ['Construction', f'Months {I["con_start"]} to {I["delivery"]} ({I["con_months"]} months)'], ['Handover', f'Project month {I["delivery"]}']], [6.0, 10.3], f'{nm}: project facts (source: Jalour financial model)', -1, bold_first_col=True)
            d.p(f'Retail accounts for {fmt(I["retail"]/I["bua"]*100,0)}% of built-up area and offices for {fmt(I["office"]/I["bua"]*100,0)}%. The model sells offices on a sellable area of {fmt(I["admin_sales_area"],0)} m2, larger than the {fmt(I["office"],0)} m2 of office built-up area; the area schedule that reconciles the two is provided after the investor signs the non-disclosure agreement and should be required in due diligence.')
        d.p('Jalour is responsible in each project for design, permits and licences, construction to core and shell, project branding, marketing, sales and collection, and for operation, management and maintenance directly or through a facility management company. Permits, licences and title status are listed in the Due Diligence Memorandum [available after the investor signs the non-disclosure agreement].')
        # 6
        d.h1('6. The Al Ahly Sabbour agreements and consents')
        d.p('The following terms are taken from the Jalour financial model and are to be verified against the signed agreements in the data room.')
        d.table([['Term', 'Green Square', 'L\'avenir'], ['Landlord share of collections', '35%', '35%'], ['Developer (Jalour) share', '65%', '65%'], ['Minimum guaranteed amount', f'EGP {fmt(G["info"]["guarantee"],0)} million over six years', f'EGP {fmt(L["info"]["guarantee"],0)} million over six years'], ['Down payment', f'EGP {fmt(G["info"]["dp"],0)} million', f'EGP {fmt(L["info"]["dp"],0)} million'],
                 ['Payment rule', '35% of collections or the guaranteed instalment, whichever is higher', 'Same'], ['Excess over the guarantee', f'Settled from year {G["info"]["excess_years"]}', f'Settled from year {L["info"]["excess_years"]}'], ['Delivery', f'Month {G["info"]["delivery"]}', f'Month {L["info"]["delivery"]}']], [5.0, 6.0, 5.3], 'Agreement terms', -1, bold_first_col=True, font=9.5)
        sch = lambda I: [I['dp']] + I['sched']
        d.table([['EGP million', 'Down payment', 'Year 1', 'Year 2', 'Year 3', 'Year 4', 'Year 5', 'Year 6', 'Total']] + [[nm] + [fmt(x, 0) for x in sch(D['info'])] + [fmt(sum(sch(D['info'])), 0)] for nm, D in PJ], [3.4, 1.9, 1.5, 1.5, 1.5, 1.5, 1.5, 1.5, 1.6], 'Minimum guarantee schedules', 1, font=9)
        d.p(f'In the plans the landlord receives EGP {fmt(G["base"]["land"],0)} million (Green Square) and EGP {fmt(L["base"]["land"],0)} million (L\'avenir), calculated on the full project sales value (EGP {fmt(G["info"]["total100"],0)} million and EGP {fmt(L["info"]["total100"],0)} million) at modelled prices.')
        d.h2('6.1 Consents')
        d.p('Al Ahly Sabbour\'s written consent is required, in each project, for:', keep=True)
        d.bullets(['allocation of units to the investor (Option A) and the investor\'s right to assign the contract;', 'any assignment of collections or encumbrance on units that affects the landlord\'s 35% share;', 'earmarking of unsold units as collateral (Option B);', 'any variation of the unit mix, prices or payment plans that changes the landlord\'s entitlement.'])
        d.p('Under the structure proposed here Jalour bears the landlord\'s 35% on the units allocated to the investor: landlord payments are unchanged and the landlord does not waive any share. Consent status: [provided after the investor signs the non-disclosure agreement]. Receipt of consent is a condition precedent to signing.')
